<script>
const roleSelect=document.getElementById('invite-role'), vehicleSelect=document.getElementById('invite-vehicle');
function inviteVehicles(){const saved=vehicleSelect.value||vehicleSelect.dataset.saved;vehicleSelect.replaceChildren();const choices=roleSelect.value==='driver'?['4-wheel truck','6-wheel truck','8-wheel truck','10-wheel truck']:['motorcycle','tricycle'];for(const value of choices){const option=new Option(value,value);option.selected=value===saved;vehicleSelect.add(option);}}
roleSelect.addEventListener('change',inviteVehicles);inviteVehicles();
</script>
